// the casing's course beds, heights over the base from the foot up to the capstone's bed (the shader's own law in round 13; since round 14 the shader's beds are the runs' law, faceBeds: r16, the second reader's finding)
export function courseBeds() {
  const w = (c) => c + 0.28 * Math.sin(c * 0.37) + 0.17 * (Math.sin(c * 1.13 + 1.7) - Math.sin(1.7));
  const beds = [0, COURSE0, COURSE0 + COURSE1];
  for (let k = 1; ; k++) { let lo = k - 2, hi = k + 2; for (let i = 0; i < 50; i++) { const m = (lo + hi) / 2; if (w(m) < k) lo = m; else hi = m; }
    const h = COURSE0 + COURSE1 + (lo + hi) / 2 * COURSE_MEAN; if (h > PYR_H - CAP_H / 2) break; beds.push(h); }
  let best = beds.length - 1; for (let i = 0; i < beds.length; i++) if (Math.abs(beds[i] - (PYR_H - CAP_H)) < Math.abs(beds[best] - (PYR_H - CAP_H))) best = i;
  return beds.slice(0, best + 1);
}
export const CAP_BED = courseBeds().pop();
