// THE AIR TO THE CASINGS: the least distance from a place to the faces of the five pyramids (each face a triangle)
function triDist(p, a, b, c) {
  const sub = (u, v) => [u[0] - v[0], u[1] - v[1], u[2] - v[2]], dot = (u, v) => u[0] * v[0] + u[1] * v[1] + u[2] * v[2];
  const ab = sub(b, a), ac = sub(c, a), ap = sub(p, a), d1 = dot(ab, ap), d2 = dot(ac, ap); let q;
  const bp = sub(p, b), d3 = dot(ab, bp), d4 = dot(ac, bp), cp = sub(p, c), d5 = dot(ab, cp), d6 = dot(ac, cp);
  const vc = d1 * d4 - d3 * d2, vb = d5 * d2 - d1 * d6, va = d3 * d6 - d5 * d4;
  if (d1 <= 0 && d2 <= 0) q = a;
  else if (d3 >= 0 && d4 <= d3) q = b;
  else if (d6 >= 0 && d5 <= d6) q = c;
  else if (vc <= 0 && d1 >= 0 && d3 <= 0) { const v = d1 / (d1 - d3); q = [a[0] + ab[0] * v, a[1] + ab[1] * v, a[2] + ab[2] * v]; }
  else if (vb <= 0 && d2 >= 0 && d6 <= 0) { const w = d2 / (d2 - d6); q = [a[0] + ac[0] * w, a[1] + ac[1] * w, a[2] + ac[2] * w]; }
  else if (va <= 0 && d4 - d3 >= 0 && d5 - d6 >= 0) { const w = (d4 - d3) / (d4 - d3 + d5 - d6); q = [b[0] + (c[0] - b[0]) * w, b[1] + (c[1] - b[1]) * w, b[2] + (c[2] - b[2]) * w]; }
  else { const dn = 1 / (va + vb + vc), v = vb * dn, w = vc * dn; q = [a[0] + ab[0] * v + ac[0] * w, a[1] + ab[1] * v + ac[1] * w, a[2] + ab[2] * v + ac[2] * w]; }
  return Math.hypot(p[0] - q[0], p[1] - q[1], p[2] - q[2]);
}
// the five pyramids [centre x, centre z, half base, height, foot level]
export function pyramids() { return [[0, 0, PYR_HALF, PYR_H, BASE_Y], ...[...QUEENS, SATELLITE].map((q) => [q[0], q[1], q[2] / 2, q[3], groundY(q[0], q[1])])]; }
let PYRS = null;
// the least distance from a place to the casing of pyramids number from to to - 1 of that list (0 the great pyramid)
export function casingAir(x, y, z, from = 0, to = 5) {
  PYRS = PYRS || pyramids(); let best = 1e9; const c = [[-1, -1], [1, -1], [1, 1], [-1, 1]], p = [x, y, z];
  for (let k = from; k < to; k++) { const [cx, cz, h, H, y0] = PYRS[k], tip = [cx, y0 + H, cz];
    for (let i = 0; i < 4; i++) { const a = c[i], b = c[(i + 1) % 4]; best = Math.min(best, triDist(p, [cx + a[0] * h, y0, cz + a[1] * h], tip, [cx + b[0] * h, y0, cz + b[1] * h])); } }
  return best;
}
