  // (r6, mend 2d) THE TAMARISKS of the flood's edge, from their own stream: the shrub of the wet margin stands on
  // the dry bank just behind the reeds, along both banks of each inlet from TAMARISK_FROM m up it to its head and a
  // little beyond: a place every TAMARISK_EVERY m of each bank, TAMARISK_SHARE of them taken, TAMARISK_OUT m out
  // from the water's edge, where the ground stands dry [x, ground, z, height, turn]. INVENTED (the kind is the
  // order's; where each stands is ours).
  rng = R.tamarisk;
  WASHES.forEach((w, k) => { for (let sAt = TAMARISK_FROM; sAt < w.reach + 14; sAt += TAMARISK_EVERY) for (const side of [-1, 1]) { const a = rng(), q = bank(k, sAt + U(-3, 3), side, U(TAMARISK_OUT[0], TAMARISK_OUT[1])), h = U(TAMARISK_H[0], TAMARISK_H[1]), t = U(0, 6.283), g = groundY(q[0], q[1]);
    if (a < TAMARISK_SHARE && g > 0.25 && dykeOff(q[0], q[1]) >= DYKE_TOP) tamarisks.push([q[0], g - 0.15, q[1], h, t]); } });
  if (rest) await rest();
  // palms along the town's dyke, from the gate as far as the last inlet's crossing before the temple (a palm about
  // every 20 m, on the dyke's landward foot)
  rng = R.dyke;
  { const D = TOWN_DYKE, cum = [0]; for (let i = 1; i < D.length; i++) cum.push(cum[i - 1] + Math.hypot(D[i][0] - D[i - 1][0], D[i][1] - D[i - 1][1]));
    let end = cum[cum.length - 1]; for (let d = 0; d < end; d += 2) { let i = 0; while (i < D.length - 2 && cum[i + 1] < d) i++; const t = (d - cum[i]) / (cum[i + 1] - cum[i]), x = lerp(D[i][0], D[i + 1][0], t), z = lerp(D[i][1], D[i + 1][1], t); if (washNear(x, z, wp)[2] === 0 && wp[0] < INLET_HALF + WASH_BANK) { end = d - 6; break; } }
    for (let d = 14; d < end; d += 20 / dens) { const dd = d + U(-5, 5); let i = 0; while (i < D.length - 2 && cum[i + 1] < dd) i++; const t = clamp((dd - cum[i]) / (cum[i + 1] - cum[i]), 0, 1), dx = D[i + 1][0] - D[i][0], dz = D[i + 1][1] - D[i][1], l = Math.hypot(dx, dz), o = U(2.6, 4.2);
      palm(lerp(D[i][0], D[i + 1][0], t) + dz / l * o, lerp(D[i][1], D[i + 1][1], t) - dx / l * o, 8, 12); } }
  if (rest) await rest();
  // FALLEN BLOCKS AND LOOSE ROCK [x, y, z, size, turn, tilt]: on the talus along the cliff's foot, thick on each
  // scree fan, and below the outcrops' faces; none under the causeway's bank (its foot is kept clear), none in a
  // wash's bed (the water of the rare rains has rolled them out)
  rng = R.rocks;
  { const rock = (x, z, a, b) => { const sz = a + (b - a) * rng() ** 2.2, turn = U(0, 6.283), tilt = U(-0.3, 0.3), y = groundY(x, z); if (causewayNear(x, z)[0] < 24 || washIn(x, z, wi)[0] > 0.4 || y < 0.6) return; rocks.push([x, looseFoot(x, z, sz, turn, y - sz * LOOSE_ROCK.sink), z, sz, turn, tilt]); };
    for (let z = -140; z < 168; z += 5) { const zz = z + U(-2, 2), fx = edgeX(zz) + cliffWidth(zz), g = gullyAt(zz), o = U(0.5, TALUS_W + 3 + g * FAN_R * 0.8); rock(fx + o, zz, 0.5, 2.4); if (g > 0.3) { const o2 = U(1, FAN_R * 0.9), z2 = zz + U(-5, 5); rock(fx + o2, z2, 0.5, 1.8); } }
    for (const [off] of OUTCROP_LINES) for (let z = -140; z < 168; z += 6) { const zz = z + U(-2.5, 2.5), u = U(0.4, OUTCROP_SCREE * 0.8), a = rng(), pres = OUTCROP_ON * smoothstep(0.02, 0.28, N0.n2(zz / 34, off * 1.7) + 0.1); if (pres > 0.3 && a < 0.8) rock(edgeX(zz) + cliffWidth(zz) + off + 9 * N0.n2(zz / 60, off) + u, zz, 0.4, 1.7); } }
  // (r6) reeds at the town's dyke's foot on the flood's side, where its foot stands in water or on wet ground: a clump
  // about every 5 m, low (a man's height and a half at the most), from a stream of their own
  rng = R.dykereeds;
  { const D = TOWN_DYKE, H = DYKE_H + 0.8, off = TOWN_DYKE_W / 2 + DYKE_BATTER * H + 0.4;
    for (let i = 0; i + 1 < D.length; i++) { const dx = D[i + 1][0] - D[i][0], dz = D[i + 1][1] - D[i][1], l = Math.hypot(dx, dz);
      for (let d = 2; d < l; d += 5) { const t = (d + U(-1.5, 1.5)) / l, o = off + U(0, 1.6), sc = U(0.45, 0.8); reed(lerp(D[i][0], D[i + 1][0], t) - dz / l * o, lerp(D[i][1], D[i + 1][1], t) + dx / l * o, sc); } } }
  if (rest) await rest();
