  { const w = WASHES[0]; let best = 1e9; for (let sAt = 0; sAt <= w.length; sAt += 2) { washAt(0, sAt, wp); const d = Math.abs(wp[0] - (foot(wp[1]) + SKEIN.off)); if (d < best) { best = d; zs = wp[1]; } } }
