  // three in each inlet: at its water's edge, between the shore's line and its head
  WASHES.forEach((w, k) => { for (let i = 0; i < 3; i++) { const sAt = lerp(44, w.reach - 8, (i + re()) / 3), side = re() < 0.5 ? -1 : 1, o = INLET_HALF * (0.45 + 0.3 * re()); washAt(k, sAt, wp); stand.push([wp[0] - Math.sin(wp[2]) * side * o, 0, wp[1] + Math.cos(wp[2]) * side * o]); } });
  // two ibis at the shallow rim of each reed bed, anywhere round it
  for (const b of REED_BEDS) for (let i = 0; i < 2; i++) { const a = ri() * 6.283, q = b[2] * (0.75 + 0.2 * ri()); ibis.push([b[0] + Math.cos(a) * q, 0, b[1] + Math.sin(a) * q * 0.7]); }
  const kite = { species: 'eagles', form: 'soar', count: 3, size: BIRD_SIZE.kite, wobble: 0.1, maxSigma: FLOCK_SIGMA, body: '#4a3626', wingC: '#3c2c20', tip: '#2a1f18', head: '#5a4632', tailC: '#4a3626' };
  const tc = [(TOWN[0] + TOWN[2]) / 2, 95, (TOWN[1] + TOWN[3]) / 2];
